import{_ as r,o as n,c as s,a4 as t}from"./chunks/framework.B-wJupoK.js";const a="/assets/image-20240715181749705.D7DA4CEo.png",o="/assets/image-20240715181959993.b_mFvt8i.png",g="/assets/image-20240715182044449.DHysV8LV.png",i="/assets/image-20240715182615579.Db8qdTxN.png",d="/assets/image-20240715182856552.cK2lTaaJ.png",p="/assets/image-20240715183454378.B2l7FxTI.png",_=JSON.parse('{"title":"HarmonyOS Next V2 状态管理@ObservedV2基本使用","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @ObservedV2/@ObservedV2.md","filePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @ObservedV2/@ObservedV2.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next V2 状态管理@ObservedV2基本使用\\n\\n## 背景\\n\\n最近**Harmony** 应用开发技术中推出了新版的状态管理技术，试用过后，直呼很香。我们来看为什么？\\n\\n因为在 **Harmony** 应用开发过程中，我们一定会碰到监听**嵌套类/深层次属性**的需求，如希望 **son**的**weight**属性变化后，可以引起UI刷新。\\n\\n![image-20240715181749705](readmd.assets/image-20240715181749705.png)\\n\\n## **@Observed**装饰器和**@ObjectLink**装饰器 \\n\\n针对以上需求，那之前，也就是所谓的 **v1** 版本是怎么做的呢？ 是通过 **@Observed**装饰器和**@ObjectLink**装饰器实现的。\\n\\n其中，这一套解决方案有一个很严重的、破坏性的问题-  必须搭配自定义组件一起使用。\\n\\n![image-20240715181959993](readmd.assets/image-20240715181959993.png)\\n\\n所以，你代码本来是这样子的🤓：\\n\\n![image-20240715182044449](readmd.assets/image-20240715182044449.png)\\n\\n为了实现深层次数据的监听，必须改造-破坏你的UI结构，要引入自定义组件，那么就变成了这样子😭：\\n\\n![image-20240715182615579](readmd.assets/image-20240715182615579.png)\\n\\n---\\n\\n**大家看看，这个代码的风格，是人干的事情吗**\\n\\n接下来，我们看看更新后的技术解决方案是怎么样的  👇👇👇👇\\n\\n## @ObservedV2装饰器和@Trace装饰器\\n\\n>  截至 2024年7月15日  v2都是试用版\\n\\n![image-20240715182856552](readmd.assets/image-20240715182856552.png)\\n\\n### 介绍\\n\\n为了增强状态管理框架对类对象中属性的观测能力，开发者可以使用**@ObservedV2**装饰器和@Trace装饰器装饰类以及类中的属性。\\n\\n其中，官网上的表达如下：\\n\\n*   **@ObservedV2**装饰器与 **@Trace** 装饰器需要配合使用，单独使用 **@ObservedV2**装饰器 **@Trace** 装饰器没有任何作用。\\n*   被 **@Trace**装饰器装饰的属性**property**变化时，仅会通知**property**关联的组件进行刷新。\\n*   在嵌套类中，嵌套类中的属性**property**被 **@Trace**装饰且嵌套类被 **@ObservedV2** 装饰时，才具有触发UI刷新的能力。\\n*   在继承类中，父类或子类中的属性**property**被 **@Trace** 装饰且该**property**所在类被 **@ObservedV2** 装饰时，才具有触发UI刷新的能力。\\n*   未被 **@Trace** 装饰的属性用在UI中无法感知到变化，也无法触发UI刷新。\\n*   **@ObservedV2** 的类实例目前不支持使用**JSON.stringify**进行序列化。\\n\\n----\\n\\n\\n\\n我们针对以上总结一下。使用的技巧也很简单\\n\\n1.  **要监听的属性要添加 @Trace 装饰器**\\n2.  **被监听的属性 所在的类要添加 @ObservedV2**\\n3.  **继承类 ，继承其中的被监听的属性时，可以等价视为是给出自己的类添加了 @Trace 装饰器监听。**\\n\\n\\n\\n![image-20240715183454378](readmd.assets/image-20240715183454378.png)\\n\\n---\\n\\n是不要对比 **@Observed**装饰器和**@ObjectLink** 要简单轻松多了？\\n\\n\\n\\n## 总结\\n\\n1.  当我们在开发中，如果碰到了监听深层次属性的需求，可以使用  **@Observed**装饰器和 **@ObjectLink**装饰器   和  **@ObservedV2**装饰器和 **@Trace**装饰器\\n2.  **@Observed**装饰器和 **@ObjectLink**装饰器 是比较稳定的技术，但是开发效率低，体验不好，对代码具有入侵型\\n3.  **@ObservedV2**装饰器和 **@Trace** 装饰器是新推出的v2的版本，目前还在试用期，大概率会成为稳定版。对代码比较友好，如果是新的业务，可以优先考虑使用它。\\n\\n\\n\\n\\n"}'),c={name:"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 @ObservedV2/@ObservedV2.md"};function b(l,e,m,O,v,V){return n(),s("div",null,[...e[0]||(e[0]=[t("",31)])])}const T=r(c,[["render",b]]);export{_ as __pageData,T as default};
